mapper.select:
SELECT 


    p.store_id = #{storeId}
    AND p.status = #{status}

        AND (p.plan_no LIKE CONCAT('%', #{keyword}, '%')
             OR EXISTS (SELECT 1 FROM ecom_shipment_plan_item pi WHERE pi.plan_id = p.id AND pi.seller_sku LIKE CONCAT('%', #{keyword}, '%')))


ORDER BY p.id DESC
